def comps(g,val=None):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; c=[]
                while st:
