    vals=[inp[a][b] for a,b in big]
    pred=[r[:] for r in inp]
    for s in singles:
        if inp[s[0]][s[1]]!=vals and inp[s[0]][s[1]] not in vals: continue
        for (dr,dc),v in zip(tr,vals):
            rr,cc=s[0]+dr,s[1]+dc
            if 0<=rr<H and 0<=cc<W and inp[rr][cc]==bg: pred[rr][cc]=v
    return sum(1 for i in range(H) for j in range(W) if pred[i][j]!=out[i][j])
